// @FIGURE_CODE_BEGIN
let state = {
    a: 3,
    b: 2,
    guides: true
};

const frame = setPlotFrame({ xDomain: [-9, 9], yDomain: [-6.75, 6.75], margin: 40 });

const axesLayer = frame.draw.group();
const guidesLayer = frame.draw.group();
const curvesLayer = frame.draw.group();
const pointsLayer = frame.draw.group();

const xAxis = axesLayer.line().stroke({color: '#000', width: 1.5});
const yAxis = axesLayer.line().stroke({color: '#000', width: 1.5});
const xArrowL = axesLayer.polygon().fill('#000');
const xArrowR = axesLayer.polygon().fill('#000');
const yArrowT = axesLayer.polygon().fill('#000');
const yArrowB = axesLayer.polygon().fill('#000');

// Axis labels
const xLabel = axesLayer.text('x').font({family: 'sans-serif', size: 14, style: 'italic'}).fill('#000');
const yLabel = axesLayer.text('y').font({family: 'sans-serif', size: 14, style: 'italic'}).fill('#000');

const guideRect = guidesLayer.rect().fill('none').stroke({color: '#00897b', width: 1.5, dasharray: '6,4'});
const asymptote1 = guidesLayer.line().stroke({color: '#f57c00', width: 1.5, dasharray: '6,4'});
const asymptote2 = guidesLayer.line().stroke({color: '#f57c00', width: 1.5, dasharray: '6,4'});
const conjugateAxis = guidesLayer.line().stroke({color: '#4fc3f7', width: 2.5});
const transverseAxis = guidesLayer.line().stroke({color: '#d32f2f', width: 2.5});

const hyperbolaRight = curvesLayer.path().fill('none').stroke({color: '#004b87', width: 2.5});
const hyperbolaLeft = curvesLayer.path().fill('none').stroke({color: '#004b87', width: 2.5});

const centerPt = pointsLayer.path().stroke({color: '#f57c00', width: 2.5, linecap: 'round'});
const v1Pt = pointsLayer.circle(10).fill('#004b87');
const v2Pt = pointsLayer.circle(10).fill('#004b87');
const cv1Pt = guidesLayer.circle(10).fill('#4fc3f7');
const cv2Pt = guidesLayer.circle(10).fill('#4fc3f7');
const f1Pt = pointsLayer.circle(10).fill('#00897b');
const f2Pt = pointsLayer.circle(10).fill('#00897b');

const arrowMarker = frame.draw.marker(10, 10, function(add) {
    add.polygon('1,2 8,5 1,8').fill('#555');
}).ref(8, 5);

function makeLabel(layer, text, color) {
    const g = layer.group();
    const leader = g.line().stroke({color: '#555', width: 1.2}).marker('end', arrowMarker);
    const txt = g.text(text).font({family: 'sans-serif', size: 12, anchor: 'middle'}).fill(color || '#000');
    txt.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    return { g, leader, txt };
}

// Labels mapped to layers based on their visibility when guides are toggled
const lblTransverse = makeLabel(guidesLayer, "Transverse axis");
const lblConjugate = makeLabel(guidesLayer, "Conjugate axis");
const lblCV1 = makeLabel(guidesLayer, "Co-vertex");
const lblCV2 = makeLabel(guidesLayer, "Co-vertex");
const lblAsym1 = makeLabel(guidesLayer, "Asymptote");
const lblAsym2 = makeLabel(guidesLayer, "Asymptote");

const lblCenter = makeLabel(pointsLayer, "Center");
const lblV1 = makeLabel(pointsLayer, "Vertex");
const lblV2 = makeLabel(pointsLayer, "Vertex");
const lblF1 = makeLabel(pointsLayer, "Focus");
const lblF2 = makeLabel(pointsLayer, "Focus");

function updateLabel(lbl, wxTarget, wyTarget, dxPx, dyPx, anchor, targetOffset) {
    const offset = (targetOffset === undefined) ? 6 : targetOffset;
    const sx = plotX(wxTarget);
    const sy = plotY(wyTarget);
    const ex = sx + dxPx;
    const ey = sy + dyPx;

    const dx = sx - ex;
    const dy = sy - ey;
    const dist = Math.sqrt(dx*dx + dy*dy);

    let targetX = sx;
    let targetY = sy;
    if (dist > offset + 2) {
        // Stop the line slightly short of the target to prevent hiding the arrowhead inside the point geometry
        targetX = sx - (dx/dist) * offset;
        targetY = sy - (dy/dist) * offset;
    }

    lbl.leader.plot(ex, ey, targetX, targetY);

    let txtY = ey;
    // Adjust Y slightly so the text baseline avoids intersecting the start of the leader line
    if (dyPx < 0) txtY -= 8;
    else if (dyPx > 0) txtY += 14;
    else txtY += 4;

    lbl.txt.text(lbl.txt.text()).attr({
        x: ex, 
        y: txtY, 
        'text-anchor': anchor
    });
}

function updatePositions() {
    if (!frame) return;
    const {a, b, guides} = state;
    const c = Math.sqrt(a*a + b*b);

    const xMin = frame.xDomain[0];
    const xMax = frame.xDomain[1];
    const yMin = frame.yDomain[0];
    const yMax = frame.yDomain[1];

    const px0 = plotX(0), py0 = plotY(0);
    const pxa = plotX(a), pyna = plotX(-a);
    const pyb = plotY(b), pynb = plotY(-b);
    const pxc = plotX(c), pync = plotX(-c);

    const pxMin = plotX(xMin), pxMax = plotX(xMax);
    const pyMin = plotY(yMin), pyMax = plotY(yMax);

    // Dynamic Axes and Base Labels
    xAxis.plot(pxMin, py0, pxMax, py0);
    yAxis.plot(px0, pyMin, px0, pyMax);

    xArrowL.plot([[pxMin, py0], [pxMin + 12, py0 - 4], [pxMin + 12, py0 + 4]]);
    xArrowR.plot([[pxMax, py0], [pxMax - 12, py0 - 4], [pxMax - 12, py0 + 4]]);
    yArrowT.plot([[px0, pyMax], [px0 - 4, pyMax + 12], [px0 + 4, pyMax + 12]]);
    yArrowB.plot([[px0, pyMin], [px0 - 4, pyMin - 12], [px0 + 4, pyMin - 12]]);

    xLabel.cx(pxMax + 20).cy(py0);
    yLabel.cx(px0).cy(pyMax - 20); // pyMax is visually the top of the grid

    guidesLayer.opacity(guides ? 1 : 0);

    guideRect.size(pxa - pyna, pynb - pyb).center(px0, py0);

    const asymLen = 20; 
    asymptote1.plot(plotX(-asymLen), plotY(-(b/a)*asymLen), plotX(asymLen), plotY((b/a)*asymLen));
    asymptote2.plot(plotX(-asymLen), plotY((b/a)*asymLen), plotX(asymLen), plotY(-(b/a)*asymLen));

    conjugateAxis.plot(px0, pyb, px0, pynb);
    transverseAxis.plot(pyna, py0, pxa, py0);

    cv1Pt.center(px0, pyb); 
    cv2Pt.center(px0, pynb); 

    centerPt.plot(`M${px0-4},${py0-4} L${px0+4},${py0+4} M${px0-4},${py0+4} L${px0+4},${py0-4}`);
    v1Pt.center(pxa, py0);
    v2Pt.center(pyna, py0);
    f1Pt.center(pxc, py0);
    f2Pt.center(pync, py0);

    // Render Hyperbolas
    const steps = 150;
    let rightPts = [], leftPts = [];
    for (let i = 0; i <= steps; i++) {
        let t = -3 + (6 * i / steps); 
        let xVal = a * Math.cosh(t);
        let yVal = b * Math.sinh(t);
        if (xVal <= xMax + 2) { 
            rightPts.push([plotX(xVal), plotY(yVal)]);
            leftPts.push([plotX(-xVal), plotY(yVal)]);
        }
    }
