    hyperbolaRight.plot(makePath(rightPts));
    hyperbolaLeft.plot(makePath(leftPts));

    // Adaptive Collision-Preventing Labels
    // Lines use offset 0 so arrow touches exactly, points use offset 7 to leave a gap around the marker
    updateLabel(lblTransverse, a/2, 0, 45, -60, 'start', 0);
