    updateLabel(lblF2, -c, 0, 0, -45, 'middle', 7);

    // Dynamically place asymptote labels within visible screen boundaries
    let t_x = 7 / a;
    let t_y = 5 / b;
    let t_asym = Math.min(t_x, t_y) * 0.8;

    let target1X = -a * t_asym;
    let target1Y = -b * t_asym;
    updateLabel(lblAsym1, target1X, target1Y, 20, 35, 'start', 0);

    let target2X = a * t_asym;
    let target2Y = -b * t_asym;
    updateLabel(lblAsym2, target2X, target2Y, -20, 35, 'end', 0);
}

